def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from collections import OrderedDict
    import time

    def decorator(func):
        cache = OrderedDict()
        stats = {'hits': 0, 'misses': 0}

        def wrapper(*args, **kwargs):
            if typed:
                key = (args, tuple(sorted(kwargs.items())))
            else:
                key = args + tuple(kwargs.values())

            current_time = timer()

            # Remove expired entries
            while cache and next(iter(cache.values()))[1] < current_time:
                cache.popitem(last=False)

            # Check if the item is in the cache and not expired
            if key in cache and cache[key][1] >= current_time:
                stats['hits'] += 1
                return cache[key][0]

            # Compute and cache the result
            result = func(*args, **kwargs)
            cache[key] = (result, current_time + ttl)

            # Evict the oldest item if the cache exceeds the maxsize
            if len(cache) > maxsize:
                cache.popitem(last=False)

            stats['misses'] += 1
            return result

        def cache_info():
            return (stats['hits'], stats['misses'], maxsize, len(cache))

        wrapper.cache_info = cache_info
        return wrapper

    return decorator

