def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    from collections import OrderedDict

    # Create a graph where each node is an element from the orderings
    # and an edge from node A to node B means that A appears before B
    graph = {}
    for ordering in orderings:
        for i, item in enumerate(ordering):
            if item not in graph:
                graph[item] = set()
            if i + 1 < len(ordering):
                graph[item].add(ordering[i + 1])

    # Function to perform a topological sort using Kahn's algorithm
    def topological_sort(graph):
        in_degree = { u : 0 for u in graph }
        for u in graph:
            for v in graph[u]:
                in_degree[v] += 1

        zero_in_degree_queue = [u for u in in_degree if in_degree[u] == 0]
        topological_ordering = []

        while zero_in_degree_queue:
            u = zero_in_degree_queue.pop(0)
            topological_ordering.append(u)
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    zero_in_degree_queue.append(v)

        # Check for cycles
        if len(topological_ordering) == len(graph):
            return topological_ordering
        else:
            raise ValueError("Graph has at least one cycle, topological sort not possible")

    try:
        return topological_sort(graph)
    except ValueError as e:
        raise ValueError("Orderings cannot be merged due to conflicting order constraints: " + str(e))

