def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []

    def add_bases(cls):
        if cls not in seen:
            seen.add(cls)
            for base in cls.__bases__:
                add_bases(base)
            result.append(cls)

    for cls in reversed(classes):
        add_bases(cls)

    # Reverse result to maintain the original order of appearance
    result.reverse()

    # Remove classes that are already bases of others
    return [cls for cls in result if all(not issubclass(c, cls) for c in result if c is not cls)]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        minimal_bases = []
        for cls in classes:
            if cls not in minimal_bases and not any(issubclass(base, cls) for base in minimal_bases):
                minimal_bases.append(cls)
        return minimal_bases
    except TypeError:
        raise TypeError("All elements in classes must be class objects")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a dictionary to track the position of each class
        class_order = {cls: i for i, cls in enumerate(classes)}
        # Set to track minimal bases
        minimal_set = set(classes)

        # Check each class and remove if it is a subclass of any other class in the list
        for cls in classes:
            for other in classes:
                if cls != other and issubclass(cls, other):
                    # If cls is a subclass of other and comes later, remove it from minimal_set
                    if class_order[cls] > class_order[other]:
                        minimal_set.discard(cls)
                        break

        # Return the minimal set of bases in their original order
        return [cls for cls in classes if cls in minimal_set]
    except TypeError as e:
        # Handle cases where issubclass() raises a TypeError (e.g., non-class types in the list)
        raise TypeError("All elements in the classes list must be class types") from e

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        seen = set()
        minimal = []
        for cls in classes:
            if cls not in seen:
                seen.add(cls)
                minimal.append(cls)
                for base in cls.__bases__:
                    if base in seen:
                        seen.remove(base)
                        minimal.remove(base)
        return minimal
    except Exception as e:
        raise ValueError(f"Error processing base classes: {e}")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        if not isinstance(classes, list) or not all(isinstance(cls, type) for cls in classes):
            raise ValueError("Input must be a list of classes.")

        minimal = []
        for cls in classes:
            if not any(issubclass(base, cls) for base in minimal):
                bases = tuple(base for base in minimal if not issubclass(cls, base))
                minimal = [cls] + [base for base in minimal if base not in bases]

        return minimal
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

