def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != len(self.edges) - 1:
        raise ValueError("Coordinate must be a tuple with the same dimension as the histogram edges minus one.")

    if not all(self.edges[i].min() <= coord[i] <= self.edges[i].max() for i in range(len(coord))):
        return  # Ignore coordinates outside the histogram edges

    indices = tuple(np.searchsorted(self.edges[i], coord[i], side='right') - 1 for i in range(len(coord)))
    if not all(0 <= index < len(self.counts) for index in indices):
        return  # Ignore if any index is out of bounds (shouldn't happen given previous checks)

    self.counts[indices] += weight

