    if not all(lower <= c <= upper for c, (lower, upper) in zip(coord, zip(self.edges[:-1], self.edges[1:]))):
        return  # Ignore coordinates outside the histogram edges

    index = tuple(
        np.searchsorted(self.edges[i+1:], coord[i], side='left')
        for i in range(len(coord))
