def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
    	:class:`list`).
    """
    try:
        if self.SQLParams.in_style == 'named':
            if not isinstance(params, collections.abc.Mapping):
                raise ValueError("For named parameter style, params must be a Mapping.")
            out_params = {str(i): params[param] for i, param in enumerate(params)}
            formatted_sql = sql % {f':{param}': f':{i}' for i, param in enumerate(params)}
        elif self.SQLParams.in_style == 'ordinal':
            if not isinstance(params, collections.abc.Sequence):
                raise ValueError("For ordinal parameter style, params must be a Sequence.")
            out_params = list(params)
            formatted_sql = sql % tuple(f':{i}' for i in range(len(params)))
        else:
            raise ValueError("Unsupported parameter style.")

        return formatted_sql, out_params
    except Exception as e:
        raise ValueError(f"Error during SQL formatting: {str(e)}") from e

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("SQL query must be a string or bytes")

    if not isinstance(many_params, Iterable):
        raise ValueError("Parameters must be an iterable")

    out_style_params = []
    try:
        formatted_sql = sql
        if self.SQLParams.in_style == 'named':
            param_pattern = re.compile(r':([a-zA-Z_][a-zA-Z0-9_]*)')
            for params in many_params:
                if not isinstance(params, Mapping):
                    raise ValueError("Parameters for named style must be a mapping")
                out_params = {}
                for match in param_pattern.finditer(sql):
                    param_name = match.group(1)
                    placeholder = self.SQLParams.out_formatter(len(out_params))
                    formatted_sql = formatted_sql.replace(':' + param_name, placeholder, 1)
                    out_params[placeholder] = params[param_name]
                out_style_params.append(out_params)
        elif self.SQLParams.in_style in ('qmark', 'numeric', 'named', 'format', 'pyformat'):
            param_pattern = re.compile(r'\?|:(\d+)|%s|%\(.*?\)s')
            for params in many_params:
                if not isinstance(params, Sequence):
                    raise ValueError("Parameters for ordinal style must be a sequence")
                out_params = []
                for match in param_pattern.finditer(sql):
                    placeholder = self.SQLParams.out_formatter(len(out_params))
                    formatted_sql = formatted_sql.replace(match.group(0), placeholder, 1)
                    if match.group(0) == '?':
                        out_params.append(params[len(out_params)])
                    elif match.group(1):
                        out_params.append(params[int(match.group(1)) - 1])
                    else:
                        out_params.append(params[len(out_params)])
                out_style_params.append(out_params)
        else:
            raise ValueError("Unsupported parameter style")
    except Exception as e:
        raise ValueError(f"Error formatting SQL query: {e}")

    return formatted_sql, out_style_params

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    import re
    from collections.abc import Iterable, Mapping, Sequence

    def convert_params(params):
        if isinstance(params, Mapping):
            return {f':{key}': value for key, value in params.items()}
        elif isinstance(params, Sequence):
            return [value for value in params]
        else:
            raise ValueError("Parameters must be a Mapping or a Sequence")

    out_style_params = []
    param_pattern = re.compile(r'(:\w+|\?)')

    if self.SQLParams.in_style == 'named':
        def replacer(match):
            param = match.group(0)
            if param in out_style_dict:
                return out_style_dict[param]
            else:
                raise ValueError(f"Parameter {param} not found in parameters")
    elif self.SQLParams.in_style == 'qmark':
        param_count = 0
        def replacer(match):
            nonlocal param_count
            if param_count < len(out_style_list):
                param_count += 1
                return f'${param_count}'
            else:
                raise ValueError("Not enough parameters provided")
    elif self.SQLParams.in_style == 'numeric':
        param_count = 0
        def replacer(match):
            nonlocal param_count
            param_count += 1
            return f':{param_count}'
    elif self.SQLParams.in_style == 'format':
        param_count = 0
        def replacer(match):
            nonlocal param_count
            param_count += 1
            return f'%({param_count})s'
    elif self.SQLParams.in_style == 'pyformat':
        param_count = 0
        def replacer(match):
            nonlocal param_count
            param_count += 1
            return f':{param_count}'
    else:
        raise ValueError("Unsupported in_style")

    formatted_sqls = []
    for params in many_params:
        if self.SQLParams.in_style in ['named', 'pyformat']:
            out_style_dict = convert_params(params)
            formatted_sql = param_pattern.sub(replacer, sql)
        else:
            out_style_list = convert_params(params)
            formatted_sql = param_pattern.sub(replacer, sql)
        formatted_sqls.append(formatted_sql)
        out_style_params.append(out_style_dict if self.SQLParams.in_style in ['named', 'pyformat'] else out_style_list)

    return formatted_sqls[0] if len(formatted_sqls) == 1 else formatted_sqls, out_style_params

