    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, (list, set)) or not isinstance(digests_used, (list, set)):
        raise ValueError("Both manifest_files and digests_used must be a list or set.")

    digests_in_manifest = set()
    for mf in manifest_files:
        if not isinstance(mf, dict):
            raise ValueError("Each manifest file entry must be a dictionary.")
        digests_in_manifest.update(mf.get('digests', []))

    missing_digests = digests_in_manifest - set(digests_used)
