def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not os.path.isdir(folder):
        raise ValueError(f"The provided folder path '{folder}' is not a valid directory.")

    package_data = defaultdict(list)

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    xml_basename = os.path.splitext(file)[0]
                    package_data[xml_basename].append({
                        'file_path': file_path,
                        'root_element': root_element.tag,
                        'content': ET.tostring(root_element, encoding='unicode')
                    })
                except ET.ParseError:
                    print(f"Failed to parse XML file: {file_path}")
                except Exception as e:
                    print(f"An error occurred while processing file {file_path}: {e}")

    return dict(package_data)

