    -------
    dict
    """
    import os

    packages = {}
    try:
        file_name = os.path.basename(file_path)
        file_folder = os.path.dirname(file_path)

        if prefix in file_name:
            if 'asset' in file_name:
                file_type = 'asset'
            elif 'rendition' in file_name:
                file_type = 'rendition'
            else:
                file_type = 'unknown'
        else:
            file_type = 'unknown'

        packages[file_name] = {
