def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            file_dict = {}
            for file_info in z.infolist():
                filename = file_info.filename
                if filename.endswith('.xml'):
                    base_name = os.path.basename(filename)
                    name_without_ext = os.path.splitext(base_name)[0]
                    if name_without_ext not in file_dict:
                        file_dict[name_without_ext] = []
                    file_dict[name_without_ext].append({
                        'filename': filename,
                        'content': z.read(file_info)
                    })
            return file_dict
    except zipfile.BadZipFile:
        raise ValueError("The file is not a valid zip file")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

