    return pretty_repr

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and right[0] == '|':
                    if left == right[1]:
                        return left
                    elif left == right[2]:
                        return left
                elif isinstance(left, tuple) and left[0] == '|':
                    if left[1] == right:
                        return right
                    elif left[2] == right:
                        return right
            elif op == '|':
                if isinstance(right, tuple) and right[0] == '&':
                    if left == right[1]:
                        return left
                    elif left == right[2]:
                        return left
                elif isinstance(left, tuple) and left[0] == '&':
                    if left[1] == right:
                        return right
                    elif left[2] == right:
                        return right
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and right[0] == '|':
                    if right[1] == ('~', left):
                        return ('&', left, right[2])
                    elif right[2] == ('~', left):
                        return ('&', left, right[1])
            elif op == '|':
                if isinstance(right, tuple) and right[0] == '&':
                    if right[1] == ('~', left):
                        return ('|', left, right[2])
                    elif right[2] == ('~', left):
                        return ('|', left, right[1])
        return expr

    new_args = deepcopy(args)
    for i in range(len(new_args)):
        new_args[i] = apply_absorption(new_args[i])
        new_args[i] = apply_negative_absorption(new_args[i])
    return new_args

