                if isinstance(right, tuple) and right[0] == '&' and isinstance(right[2], tuple) and right[2][0] == '~':
                    if right[2][1] == left:
                        return ('|', left, right[1])
                if isinstance(left, tuple) and left[0] == '&' and isinstance(left[1], tuple) and left[1][0] == '~':
                    if left[1][1] == right:
                        return ('|', right, left[2])
                if isinstance(left, tuple) and left[0] == '&' and isinstance(left[2], tuple) and left[2][0] == '~':
                    if left[2][1] == right:
                        return ('|', right, left[1])
        return expr

    new_args = []
    for arg in args:
        try:
            new_arg = apply_absorption(deepcopy(arg))
            new_args.append(new_arg)
        except Exception as e:
            print(f"Error processing expression {arg}: {e}")
            new_args.append(arg)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            op, left, right = expr
            if op == '&':
                if right == ('|', left, '_'):
                    return left
                elif right == ('|', ('~', left), '_'):
                    return ('&', left, right[2])
            elif op == '|':
                if right == ('&', left, '_'):
                    return left
                elif right == ('&', ('~', left), '_'):
                    return ('|', left, right[2])
        return expr

    return [apply_absorption(arg) for arg in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list) or len(args) != 3:
        raise ValueError("args must be a list of three expressions: [A, operator, B]")

    A, operator, B = args

    if operator == '&':
        if B == f'({A} | B)':
            return [A]
        elif B == f'(~{A} | B)':
            return [f'{A} & B']
    elif operator == '|':
        if B == f'({A} & B)':
            return [A]
        elif B == f'(~{A} & B)':
            return [f'{A} | B']

    return args

