    if not version_dirs:
        raise ValueError("version_dirs should not be empty.")

    root_inventory = {}
    try:
        with open(os.path.join(version_dirs[0], 'inventory'), 'r') as f:
            root_inventory = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Error reading root inventory: {e}")

    different_digests = {}

    for version in version_dirs:
        version_path = os.path.join(version, 'inventory')
