    root_inventory = {}
    differing_digests = {}

    try:
        # Assume there's a method to load inventory from a version directory
        root_inventory = self.load_inventory(version_dirs[0])
    except Exception as e:
        raise ValueError(f"Failed to load root inventory from {version_dirs[0]}: {e}")

