def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'
        elif os.path.isdir(path):
            namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
            if '0=ocfl_root' in namaste_files:
                return 'root'
            elif '0=ocfl_object' in namaste_files:
                return 'object'
            else:
                return 'unknown directory type'
        else:
            return 'path does not exist'
    except Exception as e:
        return f'error: {str(e)}'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'

        namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]
        if not namaste_files:
            return 'unknown'

        # OCFL Specification states that there might be multiple 0=* files, we check all
        for namaste_file in namaste_files:
            with open(os.path.join(path, namaste_file), 'r') as f:
                content = f.read().strip()
            if content == 'ocfl_1.0':
                return 'root'
            elif content.startswith('ocfl_object '):
                return 'object'
        return 'unknown'

    except FileNotFoundError:
        return 'file not found'
    except Exception as e:
        return str(e)

