def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    factor = 1
    if size[-1].isalpha():
        suffix = size[-1].upper()
        size = size[:-1]
        if suffix == 'K':
            factor = 1000
        elif suffix == 'M':
            factor = 1000 ** 2
        elif suffix == 'G':
            factor = 1000 ** 3
        elif suffix == 'T':
            factor = 1000 ** 4
        elif suffix == 'P':
            factor = 1000 ** 5
        elif suffix == 'E':
            factor = 1000 ** 6
        else:
            raise ValueError(f"Unknown size suffix: {suffix}")

    try:
        value = int(size)
    except ValueError:
        try:
            value = float(size)
        except ValueError:
            raise ValueError(f"Invalid size value: {size}")

    return int(value * factor)

