def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        sc = c.__subclasses__()
        for subcls in sc:
            if subcls not in seen:
                seen.add(subcls)
                queue.append(subcls)

    return seen

