def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Simple regex for POSIX shell-like splitting
        return re.findall(r'''(?u)\S+''', s)
    elif platform == 0:  # Windows/CMD
        # Regex to handle Windows command line parsing
        return re.findall(r'''(?u)"(?:\\"|[^"])*"|[^ ]+''', s)
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1 for POSIX, or 0 for Windows/CMD.")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:
        # POSIX style
        pattern = r"""(['"])(\\.|(?!\1)[^\\])*?\1|\S+"""
    elif platform == 0:
        # Windows/CMD style
        pattern = r"""(["'])(?:\\["']|\\.)*?\1|[^ \t"]+"""
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1, or 0.")

    return re.findall(pattern, s)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Regular expression for splitting POSIX command line
        posix_regex = r"""((?:[^"'\s\\]|\\.|"(?:\\.|[^"])*"|'(?:\\.|[^'])*')+)"""
        return re.findall(posix_regex, s)

    elif platform == 0:  # Windows/CMD
        # Regular expression for splitting Windows/CMD command line
        windows_regex = r"""((?:[^"^\s^\\]|\\.|"(?:\\.|[^"])*")+)"""
        return re.findall(windows_regex, s)

    else:
        raise ValueError("Invalid platform specified. Use 'this', 1 for POSIX, or 0 for Windows/CMD.")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    from pathlib import Path
    import subprocess

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive {archive_path} does not exist.")

    tmp_path = Path(tmp_path)
    tmp_path.mkdir(parents=True, exist_ok=True)

    if filename:
        extract_path = tmp_path / filename
    else:
        extract_path = tmp_path / os.path.basename(archive_path).rsplit('.', 1)[0]

    try:
        if archive_path.endswith(('.tar.gz', '.tgz')):
            subprocess.run(
                ['tar', '-xzf', archive_path, '-C', str(tmp_path)],
                check=True
            )
        elif archive_path.endswith(('.tar.bz2', '.tbz2')):
            subprocess.run(
                ['tar', '-xjf', archive_path, '-C', str(tmp_path)],
                check=True
            )
        elif archive_path.endswith('.zip'):
            subprocess.run(
                ['unzip', archive_path, '-d', str(tmp_path)],
                check=True
            )
        else:
            raise ValueError("Unsupported archive type")

        # Assuming the extracted content is directly in the extract_path
        if filename and not os.path.exists(extract_path):
            extract_path = tmp_path / os.listdir(tmp_path)[0]

        return f"file://{extract_path}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")

    except Exception as e:
        shutil.rmtree(tmp_path, ignore_errors=True)
        raise e

    finally:
        # Optionally, clean up the extracted files if they are not needed
        # shutil.rmtree(extract_path, ignore_errors=True)
        pass

