def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mean = 0.2
    sigma = 0.1
    try:
        return (1.0 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((np.array(x) - mean) / sigma) ** 2)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mean = 0.2
    sigma = 0.1
    try:
        return np.exp(-((x - mean) ** 2) / (2 * sigma ** 2)) / (sigma * np.sqrt(2 * np.pi))
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import toml
    import os
    from logging import LogRecord

    config_dict = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename) as fd:
                raw_config = fd.read()
                config = toml.loads(raw_config)
                config_dict[filename] = config
        except FileNotFoundError:
            errors.append(LogRecord(name='load_configurations', level=logging.ERROR, pathname=filename, lineno=0,
                                   msg=f"Configuration file not found: {filename}", args=(), exc_info=None))
        except toml.TomlDecodeError as e:
            errors.append(LogRecord(name='load_configurations', level=logging.ERROR, pathname=filename, lineno=0,
                                   msg=f"Failed to parse TOML configuration file: {filename}", args=(), exc_info=e))

    if overrides:
        for key, value in overrides.items():
            if key in config_dict:
                config_dict[key].update(value)

    if resolve_env:
        for filename, config in config_dict.items():
            try:
                config_dict[filename] = _resolve_environment_variables(config)
            except Exception as e:
                errors.append(LogRecord(name='load_configurations', level=logging.ERROR, pathname=filename, lineno=0,
                                       msg=f"Failed to resolve environment variables in configuration file: {filename}", args=(), exc_info=e))

    return config_dict, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import logging.config
    import os
    import json

    config_dicts = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_content = file.read()
                if filename.endswith('.json'):
                    config_dict = json.loads(config_content)
                elif filename.endswith('.yaml') or filename.endswith('.yml'):
                    import yaml
                    config_dict = yaml.safe_load(config_content)
                else:
                    raise ValueError(f"Unsupported config file format: {filename}")

                if resolve_env:
                    config_dict = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config_dict.items()}

                if overrides:
                    config_dict.update(overrides)

                config_dicts[filename] = config_dict

        except Exception as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR,
                                       pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
            log_records.append(record)

    return config_dicts, log_records

