    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    for arg_name, arg_value in args.items():
        if isinstance(arg_value, str) and "length" in arg_value:
            try:
                max_length = int(arg_value.split(":")[1])
            except (IndexError, ValueError):
                raise ValueError(f"Invalid length specification for {arg_name}")

            if len(arg_value.split(":")[0]) > max_length:
                raise ValueError(f"Value for {arg_name} is longer than specified length {max_length}")
        elif isinstance(arg_value, (list, tuple)):
            for item in arg_value:
                if isinstance(item, str) and "length" in item:
                    try:
                        max_length = int(item.split(":")[1])
                    except (IndexError, ValueError):
                        raise ValueError(f"Invalid length specification for item in {arg_name}")

                    if len(item.split(":")[0]) > max_length:
                        raise ValueError(f"Value in {arg_name} is longer than specified length {max_length}")

