def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    try:
        parser = self.parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg_name, arg_value in values_dict.items():
        try:
            arg = parser.get_argument(f"--{arg_name}")
        except argparse.ArgumentError:
            try:
                arg = parser.get_argument(f"-{arg_name}")
            except argparse.ArgumentError:
                continue  # Argument not found in parser, skip it

        if arg.type is not None:
            try:
                values_dict[arg_name] = arg.type(arg_value)
            except (ValueError, TypeError) as e:
                raise ValueError(f"Error converting {arg_name}: {e}")

