    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    try:
        # Assuming self has a method to get the cli options
        cli_options = self.get_cli_options()
        subparser = root_subparsers.add_parser(self.name, help=self.description)
        for option in cli_options:
